namespace RyanAssets.GameFeel {
    /// <summary>
    /// The kit's pooled particle effects (prefabs generated by Ryan &gt; Game Feel &gt; Rebuild).
    /// Values are stored in assets, so only ever append new kinds at the end.
    /// </summary>
    public enum FxKind {
        /// <summary>Small ground puff: footsteps, jumps, landings, things set down.</summary>
        DustPuff = 0,
        /// <summary>Bright streaks thrown out from a hit.</summary>
        Sparks = 1,
        /// <summary>Colourful paper burst for wins, finishes and records.</summary>
        Confetti = 2,
        /// <summary>Gold glints popping up and out: coins collected, money earned.</summary>
        CoinBurst = 3,
        /// <summary>Fireball, sparks and a little smoke: grenades, small blasts.</summary>
        ExplosionSmall = 4,
        /// <summary>Big fireball, debris sparks, smoke column and ground ring.</summary>
        ExplosionLarge = 5,
        /// <summary>A few slow grey puffs drifting up.</summary>
        Smoke = 6,
        /// <summary>Green crosses and glow rising: heals, buffs.</summary>
        Heal = 7,
        /// <summary>Flat expanding ring on the ground: impacts, stomps, area pulses.</summary>
        ShockwaveRing = 8,
        /// <summary>Looping vertical light pillar: objectives, drop zones. Use <see cref="GameFx.Start"/>.</summary>
        BeaconBeam = 9,
        /// <summary>Looping glowing particle trail behind a moving object. Use <see cref="GameFx.Attach"/>.</summary>
        Trail = 10,
    }
}
